"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["26231"],{76024(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modalidade_selecionada.codigo_obrigatorio","status":422,"titulo":"C\xf3digo da modalidade \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.selecao.modalidade_selecionada.codigo_obrigatorio","requisitos":[],"oQueAconteceu":["Uma modalidade selecionada n\xe3o tem `codigo`, ou tem o campo vazio ou s\xf3 com\\nespa\xe7os em branco. \xc9 o primeiro campo conferido na cria\xe7\xe3o de uma\\nmodalidade \u2014 antes de qualquer outra confer\xeancia, incluindo as de coer\xeancia de\\ncomposi\xe7\xe3o e remanejamento (ver\\n[`composicao_origem_obrigatoria`](/erros/uniplus.selecao.modalidade_selecionada.composicao_origem_obrigatoria)),\\nporque o c\xf3digo \xe9 a identidade da modalidade dentro da oferta: \xe9 ele que\\n`composicaoOrigemCodigo`, `remanejamentoDestino`, `remanejamentoPar` e\\n`remanejamentoFallback` de outras modalidades referenciam.","**`codigo` n\xe3o vem do corpo do pedido da defini\xe7\xe3o de distribui\xe7\xe3o de vagas** \u2014 \xe9\\ncopiado do cadastro de modalidades de Configura\xe7\xe3o, no momento em que a\\nmodalidade \xe9 selecionada (`IModalidadeReader`). O pr\xf3prio cadastro j\xe1 exige\\nesse campo na escrita; pela defini\xe7\xe3o de distribui\xe7\xe3o de vagas, este c\xf3digo\\ns\xf3 aparece se a modalidade estiver gravada no cadastro de um jeito que\\ncontorna essa valida\xe7\xe3o \u2014 a confer\xeancia aqui \xe9 defesa em profundidade, n\xe3o a\\nprimeira linha.","N\xe3o acumula com nenhuma outra viola\xe7\xe3o \u2014 \xe9 a primeira que falhar que\\ninterrompe a cria\xe7\xe3o da modalidade."],"comoResolver":["O campo que falta n\xe3o est\xe1 no corpo do pedido que voc\xea enviou \u2014 est\xe1 na modalidade\\ncadastrada em Configura\xe7\xe3o. Diferente de outros campos desta s\xe9rie, o\\n`Codigo` de uma modalidade \xe9 **imut\xe1vel**: o comando de atualiza\xe7\xe3o do\\ncadastro n\xe3o o aceita como campo edit\xe1vel, ent\xe3o n\xe3o h\xe1 como corrigi-lo na\\nmesma modalidade. Investigue como ela foi gravada sem esse campo; a\\ncorre\xe7\xe3o prov\xe1vel \xe9 recriar a modalidade com o c\xf3digo preenchido, em vez de\\ntentar editar a existente."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modalidade selecionada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);